import{d as c,C as t,o as u,c as m,j as a,a as s,E as o,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第五十三章","description":"从大道与邪径到宫室奢华、田仓荒虚，理解盗夸的治理批评。","frontmatter":{"title":"道德经第五十三章","description":"从大道与邪径到宫室奢华、田仓荒虚，理解盗夸的治理批评。","category":"guide","aliases":["道德经第五十三章","老子第五十三章","dao de jing chapter 53"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-53.md","filePath":"daoism/dao-de-jing/chapter-53.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-53.md"},_=c({...p,setup(g){const n=[{id:"fear-of-imposed-action",label:"唯施是畏",showLabel:!0,sentences:[["使我",{text:"介然",glossary:"jieran"},"有知，行于大道，唯",{text:"施",glossary:"shi"},"是畏。"]],note:["【白话】假使我稍稍有一点认识，行走在大道上，我所戒惧的，只是出于己意的施作、强加造为。","【王弼注择要】「行大道于天下，唯施为之是畏也。」王弼明确从施为来解释施，不在这里作施舍义。","【读法】介然本页暂读作稍有、微小之状，王注未独立细释这个词，不把这一字训冒称原注定论。施依所引注读 shī；别有从偏行释施的路径，本页不混入。"]},{id:"broad-way-and-shortcuts",label:"大道甚夷，而民好径",showLabel:!0,sentences:[["大道甚",{text:"夷",glossary:"yi"},"，而民好",{text:"径",glossary:"jing"},"。"]],note:["【白话】大道本来十分平坦，人们却偏好走小径、邪径。与上段相连，问题不在大道难行，而在舍开大道，另寻偏途。","【王弼注择要】「大道荡然正平，而民犹尚舍之而不由，好从邪径。」注又追问施为是否进一步堵塞大道。","【读法】夷在此复用平坦义，不取第十四章视而不见的义项。径不只是物理上的短路，而在章内逐渐显成偏离正道的取径。"]},{id:"palace-fields-and-granaries",label:"朝甚除，田甚芜，仓甚虚",showLabel:!0,sentences:[[{text:"朝",glossary:"chao"},"甚",{text:"除",glossary:"chu"},"，田甚",{text:"芜",glossary:"wu"},"，仓甚",{text:"虚",glossary:"xu"},"；"]],note:["【白话】朝廷宫室极其整饬洁好，田地却十分荒芜，仓廪却十分空虚。三处景象并置，显出奢盛与基本生计之间的失衡。","【王弼注择要】「朝，宫室也。除，絜好也。」又说「朝甚除则田甚芜、仓甚虚，设一而众害生也」，把一处奢设与多处损害相连。","【读法】除不是铲除朝廷，虚在仓虚中是空乏，不可套用道家虚静的褒义。此段针对治理结果的对照，不只作审美上的朴素劝告。"]},{id:"lavishness-and-stolen-standing",label:"是谓盗夸",showLabel:!0,sentences:[["服",{text:"文彩",glossary:"wencai"},"，带利剑，",{text:"厌",glossary:"yan"},"饮食，财货有余，是谓",{text:"盗夸",glossary:"daokua"},"。"]],note:["【白话】身穿华美有文彩的衣服，佩带锋利的剑，饱享丰盛饮食，财货又积存有余；在前段田荒仓空的处境下，这就叫盗取而夸耀。","【王弼注择要】「凡物不以其道得之则皆邪也，邪则盗也。」注又以「窃位也」说不以其道而得的夸耀，将问题连到占据地位的正当性。","【读法】厌在此为饱足，不是厌恶食物。王注以得之之道辨盗夸，不把所有衣饰、财富或适当饮食一概称作盗；须连田仓与宫室的对照来读。"]},{id:"judgment-of-the-way",label:"非道也哉",showLabel:!0,sentences:[["非道也哉！"]],note:["【白话】这难道是合于道的吗！这里以强烈的感叹，否定前述舍本逐奢、得之非道的情形。","【读法】结尾连前段王注以明非道则皆盗夸的取径，回扣开头行于大道。它不只批评炫耀的样子，还追问奢盛如何取得、由谁付出代价。","【校读】旧稿末尾非道也哉！。存在重复终止标点，本页只删除感叹号后的句号；经文字词不改，所据录文未提供本站这一套现代标点。"]}],r=[{id:"jieran",term:"介然",sense:1},{id:"shi",term:"施",sense:1},{id:"yi",term:"夷",sense:2},{id:"jing",term:"径",sense:1},{id:"chao",term:"朝",sense:1},{id:"chu",term:"除",sense:1},{id:"wu",term:"芜",sense:1},{id:"xu",term:"虚",sense:1},{id:"wencai",term:"文彩",sense:1},{id:"yan",term:"厌",sense:1},{id:"daokua",term:"盗夸",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十三章",tabindex:"-1"},[s("道德经第五十三章 "),a("a",{class:"header-anchor",href:"#道德经第五十三章","aria-label":'Permalink to "道德经第五十三章"'},"​")],-1)),o(i,{title:"大道甚夷，为什么却走上炫富的邪径",summary:"本章由畏施、好径起笔，随即并置宫室整饬与田荒仓空，再以衣食财货的奢盛揭出盗夸。王弼把施依施为解释，将不以其道而得与窃位相连，批评的重心在得之之道与治理的后果。",points:[{label:"先读",text:"唯施是畏在本页依王注读施为之可畏，施读 shī，不静默换成偏行的别训。"},{label:"再辨",text:"夷为平坦；宫室越整饬，田仓越荒虚的对照，将问题落到资源与民生。"},{label:"后看",text:"盗夸不只说个人爱炫耀，更连不以其道得之与窃位；末句删除旧稿重复句号。"}],hint:"朝读 cháo，好径的好读 hào，厌饮食的厌读 yàn、取饱足义，夸读 kuā。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"大道甚夷，而民好径。",tone:"大道与偏途",guide:"不是大道本来险僻，而是舍正平去从邪径。"},{text:"朝甚除，田甚芜，仓甚虚；",tone:"奢盛与民生的对照",guide:"观察宫室的整饬由什么支撑，田仓又付出什么代价。"},{text:"是谓盗夸。非道也哉！",tone:"追问得之之道",guide:"炫耀之外更须问所得是否有道，别把结尾读成单纯审美好恶。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=b("",15))])}}});export{y as __pageData,_ as default};
